package ru.mirea.orbita;
import android.content.Context;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import java.security.KeyStore;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import org.json.JSONObject;

/** Auth tokens stay encrypted using a device-local, non-exportable Android Keystore key. */
public final class TeamConnection {
 private static final String ALIAS="orbita.team.session.v1";
 private static javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (javax.crypto.SecretKey)store.getKey(ALIAS,null);}
 public static synchronized String read(Context c){try{String value=c.getSharedPreferences("team-auth",0).getString("session",null);if(value==null)return "{}";byte[] packed=android.util.Base64.decode(value,0),iv=new byte[12],encrypted=new byte[packed.length-12];System.arraycopy(packed,0,iv,0,12);System.arraycopy(packed,12,encrypted,0,encrypted.length);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new String(cipher.doFinal(encrypted),"UTF-8");}catch(Exception e){return "{}";}}
 public static synchronized boolean write(Context c,String json){try{if(json==null||json.length()>12000)return false;JSONObject data=new JSONObject(json);if(data.length()==0)return c.getSharedPreferences("team-auth",0).edit().remove("session").commit();String server=data.getString("server");java.net.URI url=new java.net.URI(server);if(!"https".equals(url.getScheme())||url.getHost()==null||url.getUserInfo()!=null||url.getQuery()!=null||url.getFragment()!=null||!url.getPath().isEmpty())return false;String token=data.optString("token");if(!token.isEmpty()&&!token.matches("[A-Za-z0-9_-]{43}"))return false;Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] encoded=cipher.doFinal(json.getBytes("UTF-8")),iv=cipher.getIV(),packed=new byte[iv.length+encoded.length];System.arraycopy(iv,0,packed,0,iv.length);System.arraycopy(encoded,0,packed,iv.length,encoded.length);return c.getSharedPreferences("team-auth",0).edit().putString("session",android.util.Base64.encodeToString(packed,android.util.Base64.NO_WRAP)).commit();}catch(Exception e){return false;}}
 public static JSONObject request(Context c,String method,String path,String body,String sessionSnapshot){JSONObject result=new JSONObject();javax.net.ssl.HttpsURLConnection connection=null;try{if(!path.matches("/api/[A-Za-z0-9_/?=&%.-]{1,500}")||path.contains("..")||!("GET".equals(method)||"POST".equals(method)||"PATCH".equals(method)||"DELETE".equals(method)))throw new Exception("Неверный запрос");JSONObject auth=new JSONObject(sessionSnapshot);String server=auth.optString("server");if(server.isEmpty())throw new Exception("Сначала укажи сервер команды");connection=(javax.net.ssl.HttpsURLConnection)new java.net.URL(server+path).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(20000);connection.setRequestMethod(method);connection.setRequestProperty("Accept","application/json");String token=auth.optString("token");if(!token.isEmpty())connection.setRequestProperty("Authorization","Bearer "+token);if(!"GET".equals(method)){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] payload=(body==null?"{}":body).getBytes("UTF-8");if(payload.length>65536)throw new Exception("Запись слишком большая");try(java.io.OutputStream out=connection.getOutputStream()){out.write(payload);}}int status=connection.getResponseCode();java.io.InputStream stream=status>=400?connection.getErrorStream():connection.getInputStream();java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();if(stream!=null)try(java.io.InputStream input=stream){byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>2000000)throw new Exception("Ответ сервера слишком большой");}}result.put("status",status);result.put("body",bytes.toString("UTF-8"));}catch(Exception error){try{result.put("status",0);result.put("body",new JSONObject().put("error",error.getMessage()==null?"Нет соединения с сервером":error.getMessage()).toString());}catch(Exception ignored){}}finally{if(connection!=null)connection.disconnect();}return result;}
}
